from z3 import *
import itertools

n = 23

edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f'e_{i}_{j}')

def e(u, v):
    """Get edge variable, handling ordering"""
    return edges[(min(u,v), max(u,v))]

solver = Solver()

# Degree constraints
for v in range(n):
    deg_v = Sum([If(e(u,v), 1, 0) for u in range(n) if u != v])
    solver.add(deg_v >= 3)
    solver.add(deg_v <= 6)

# Forbid 3-cycles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add(Not(And(e(i,j), e(i,k), e(j,k))))

print("Added 3-cycle constraints")

# Forbid 4-cycles
count4 = 0
for a in range(n):
    for b in range(a+1, n):
        for c in range(a+1, n):
            if c == b: continue
            for d in range(a+1, n):
                if d == b or d == c: continue
                # 4-cycle a-b-c-d-a
                solver.add(Not(And(e(a,b), e(b,c), e(c,d), e(a,d))))
                # 4-cycle a-b-d-c-a
                solver.add(Not(And(e(a,b), e(b,d), e(c,d), e(a,c))))
                # 4-cycle a-c-b-d-a
                solver.add(Not(And(e(a,c), e(b,c), e(b,d), e(a,d))))
                count4 += 3

print(f"Added {count4} 4-cycle constraints")

# Forbid 5-cycles
count5 = 0
for a in range(n):
    for b in range(a+1, n):
        for c in range(a+1, n):
            if c == b: continue
            for d in range(a+1, n):
                if d == b or d == c: continue
                for e_ in range(a+1, n):
                    if e_ == b or e_ == c or e_ == d: continue
                    for perm in itertools.permutations([b,c,d,e_]):
                        x1, x2, x3, x4 = perm
                        solver.add(Not(And(
                            e(a, x1),
                            e(x1, x2),
                            e(x2, x3),
                            e(x3, x4),
                            e(x4, a)
                        )))
                        count5 += 1

print(f"Added {count5} 5-cycle constraints")

print("Solving...")
result = solver.check()
print(f"Result: {result}")

if result == sat:
    model = solver.model()
    edge_list = []
    for (i,j), var in edges.items():
        if model[var]:
            edge_list.append((i,j))
    print(f"Found graph with {len(edge_list)} edges")
    print(f"Edges: {sorted(edge_list)}")

    degs = [0]*n
    for u,v in edge_list:
        degs[u] += 1
        degs[v] += 1
    print(f"Degrees: {degs}")
else:
    print("UNSATISFIABLE")
